-- Typed request and runner/service state. JSON is confined to validation and output.
pub type StepDefinition = StepDefinition {
  id: String,
  needs: List(String),
  amount: Int,
  failures: Int
}

pub type Checkpoint = AfterBegin | AfterCall

pub type Command
  = Start(String)
  | Tick(Option(Checkpoint))
  | Advance(Int)
  | Observe
  | Crash
  | Restart
  | Cancel(String)

pub type Workflow = Workflow {
  steps: List(StepDefinition),
  commands: List(Command),
  max_attempts: Int,
  retry_delay: Int
}

pub type StepStatus = Pending | Running | Succeeded | Failed | Blocked | Cancelled deriving (Eq)
pub type RunStatus = Active | SucceededRun | FailedRun | Cancelling | CancelledRun deriving (Eq)

pub type StepState = StepState {
  id: String,
  status: StepStatus,
  attempts: Int,
  ready_at: Int
}

pub type RunState = RunState {
  id: String,
  status: RunStatus,
  cancel_requested: Bool,
  steps: List(StepState)
}

pub type ActionKey = ActionKey { run_id: String, step_id: String }
pub type CallKind = ExecuteCall | LookupCall deriving (Eq)
pub type CallOutcome = Applied | Replayed | Transient | Found | Missing deriving (Eq)
pub type ServiceCall = ServiceCall { kind: CallKind, key: ActionKey, attempt: Int, outcome: CallOutcome }
pub type Effect = Effect { key: ActionKey, amount: Int }
pub type MockService = MockService { calls: List(ServiceCall), effects: List(Effect) }

pub type Snapshot = Snapshot { now: Int, up: Bool, runs: List(RunState) }
pub type Simulator = Simulator {
  now: Int,
  up: Bool,
  runs: List(RunState),
  service: MockService,
  observations: List(Snapshot)
}

pub type Action = Action { run: RunState, step: StepState, definition: StepDefinition }
pub type ServiceResult = ServiceResult { service: MockService, outcome: CallOutcome }

pub fn time_limit() : Int = 2147483647

import Data.List (..)
import Data.Foldable (..)
import Data.String (..)
import Data.Result (..)
import Json (..)
import Domain (..)
import Runner (snapshot)

fn step_status(status : StepStatus) : String =
  match status of
    Pending => "pending"
    Running => "running"
    Succeeded => "succeeded"
    Failed => "failed"
    Blocked => "blocked"
    Cancelled => "cancelled"

fn run_status(status : RunStatus) : String =
  match status of
    Active => "active"
    SucceededRun => "succeeded"
    FailedRun => "failed"
    Cancelling => "cancelling"
    CancelledRun => "cancelled"

fn step_json(step : StepState) : Json =
  JObj([("id", JStr(step.id)), ("status", JStr(step_status(step.status))),
    ("attempts", JInt(step.attempts)), ("ready_at", JInt(step.ready_at))])

fn run_json(run : RunState) : Json =
  JObj([("id", JStr(run.id)), ("status", JStr(run_status(run.status))),
    ("cancel_requested", JBool(run.cancel_requested)), ("steps", JArr(map(step_json, run.steps)))])

fn snapshot_fields(state : Snapshot) : List((String, Json)) =
  [("now", JInt(state.now)), ("up", JBool(state.up)), ("runs", JArr(map(run_json, state.runs)))]

fn snapshot_json(state : Snapshot) : Json = JObj(snapshot_fields(state))

fn key_json(key : ActionKey) : Json = JArr([JStr(key.run_id), JStr(key.step_id)])

fn call_json(call : ServiceCall) : Json =
  JObj([("kind", JStr(if call.kind == ExecuteCall then "execute" else "lookup")), ("key", key_json(call.key)),
    ("attempt", JInt(call.attempt)), ("outcome", JStr(outcome_text(call.outcome)))])

fn outcome_text(outcome : CallOutcome) : String =
  match outcome of
    Applied => "applied"
    Replayed => "replayed"
    Transient => "transient"
    Found => "found"
    Missing => "missing"

fn effect_json(entry : Effect) : Json =
  JObj([("key", key_json(entry.key)), ("amount", JInt(entry.amount))])

pub fn result_json(sim : Simulator) : Json =
  let final_fields = append(snapshot_fields(snapshot(sim)),
    [("calls", JArr(map(call_json, sim.service.calls))), ("effects", JArr(map(effect_json, sim.service.effects)))])
  JObj([("observations", JArr(map(snapshot_json, sim.observations))), ("final", JObj(final_fields))])

pub fn response_json(result : Result(Simulator, String)) : Json =
  match result of
    Ok(sim) => JObj([("ok", JBool(true)), ("result", result_json(sim))])
    Err(code) => JObj([("ok", JBool(false)), ("error", JObj([("code", JStr(code))]))])

import Data.List (..)
import Data.Foldable (..)
import Data.Result (..)
import Domain (..)
import Service (..)

pub fn new_simulator() : Simulator = Simulator { now = 0, up = true, runs = [], service = new_service(), observations = [] }
pub fn snapshot(sim : Simulator) : Snapshot = Snapshot { now = sim.now, up = sim.up, runs = sim.runs }

fn new_step(now : Int, d : StepDefinition) : StepState = StepState { id = d.id, status = Pending, attempts = 0, ready_at = now }
fn replace_step(run : RunState, replacement : StepState) : RunState = RunState { ..run, steps = map(\(s) -> if s.id == replacement.id then replacement else s, run.steps) }
fn replace_run(sim : Simulator, replacement : RunState) : Simulator = Simulator { ..sim, runs = map(\(r) -> if r.id == replacement.id then replacement else r, sim.runs) }
fn definition_for(defs : List(StepDefinition), id : String) : Option(StepDefinition) = find(\(d) -> d.id == id, defs)

fn deps_done(run : RunState, d : StepDefinition) : Bool = all(\(dep) -> any(\(s) -> s.id == dep && s.status == Succeeded, run.steps), d.needs)
fn select_step(now : Int, inflight : Bool, run : RunState, states : List(StepState), defs : List(StepDefinition)) : Option(Action) =
  match (states, defs) of
    (Cons(s, ss), Cons(d, ds)) =>
      let eligible = if inflight then s.status == Running else run.status == Active && s.status == Pending && s.ready_at <= now && deps_done(run, d)
      if eligible then Some(Action { run = run, step = s, definition = d }) else select_step(now, inflight, run, ss, ds)
    _ => None
fn select_run(now : Int, inflight : Bool, runs : List(RunState), defs : List(StepDefinition)) : Option(Action) =
  match runs of
    Nil => None
    Cons(r, rest) => match select_step(now, inflight, r, r.steps, defs) of
      Some(a) => Some(a)
      None => select_run(now, inflight, rest, defs)
pub fn select_action(sim : Simulator, workflow : Workflow) : Option(Action) =
  match select_run(sim.now, true, sim.runs, workflow.steps) of
    Some(a) => Some(a)
    None => select_run(sim.now, false, sim.runs, workflow.steps)

fn all_succeeded(xs : List(StepState)) : Bool = all(\(s) -> s.status == Succeeded, xs)
fn block_pending(run : RunState) : RunState = RunState { ..run, steps = map(\(s) -> if s.status == Pending then StepState { ..s, status = Blocked } else s, run.steps) }
fn finish_success(run : RunState) : RunState = if all_succeeded(run.steps) then RunState { ..run, status = SucceededRun } else run

fn do_action(sim : Simulator, workflow : Workflow, action : Action, checkpoint : Option(Checkpoint)) : Result(Simulator, String) =
  let running = if action.step.status == Pending then StepState { ..action.step, status = Running, attempts = action.step.attempts + 1 } else action.step
  let begun_run = replace_step(action.run, running)
  let begun = replace_run(sim, begun_run)
  match checkpoint of
    Some(AfterBegin) => Ok(Simulator { ..begun, up = false })
    _ =>
      let key = ActionKey { run_id = action.run.id, step_id = running.id }
      if action.run.status == Cancelling then
        let looked = lookup(begun.service, key, running.attempts)
        match checkpoint of
          Some(AfterCall) => Ok(Simulator { ..begun, service = looked.service, up = false })
          _ =>
            let final_step = if looked.outcome == Found then StepState { ..running, status = Succeeded } else StepState { ..running, status = Cancelled }
            let final_run = RunState { ..replace_step(begun_run, final_step), status = CancelledRun }
            Ok(replace_run(Simulator { ..begun, service = looked.service }, final_run))
      else
        let called = execute(begun.service, key, action.definition.amount, running.attempts, action.definition.failures)
        match checkpoint of
          Some(AfterCall) => Ok(Simulator { ..begun, service = called.service, up = false })
          _ =>
            if called.outcome == Transient then
              if running.attempts >= workflow.max_attempts then
                let failed = block_pending(RunState { ..replace_step(begun_run, StepState { ..running, status = Failed }), status = FailedRun })
                Ok(replace_run(Simulator { ..begun, service = called.service }, failed))
              elif sim.now + workflow.retry_delay > time_limit() then Err("TIME_OVERFLOW")
              else
                let retry = StepState { ..running, status = Pending, ready_at = sim.now + workflow.retry_delay }
                Ok(replace_run(Simulator { ..begun, service = called.service }, replace_step(begun_run, retry)))
            else
              let completed = replace_step(begun_run, StepState { ..running, status = Succeeded })
              Ok(replace_run(Simulator { ..begun, service = called.service }, finish_success(completed)))

pub fn tick(sim : Simulator, workflow : Workflow, checkpoint : Option(Checkpoint)) : Result(Simulator, String) =
  if not(sim.up) then Err("PROCESS_DOWN")
  else match select_action(sim, workflow) of
    None => Ok(sim)
    Some(action) => do_action(sim, workflow, action, checkpoint)

fn cancel_run(sim : Simulator, id : String) : Result(Simulator, String) =
  match find(\(r) -> r.id == id, sim.runs) of
    None => Err("UNKNOWN_RUN")
    Some(run) =>
      match run.status of
        SucceededRun => Ok(sim)
        FailedRun => Ok(sim)
        CancelledRun => Ok(sim)
        _ =>
          let changed = RunState { ..run, cancel_requested = true, steps = map(\(s) -> if s.status == Pending then StepState { ..s, status = Cancelled } else s, run.steps) }
          let has_running = any(\(s) -> s.status == Running, changed.steps)
          let final_run = if has_running then RunState { ..changed, status = Cancelling } else RunState { ..changed, status = CancelledRun }
          Ok(replace_run(sim, final_run))

pub fn apply_command(sim : Simulator, workflow : Workflow, command : Command) : Result(Simulator, String) =
  match command of
    Observe => Ok(Simulator { ..sim, observations = append(sim.observations, [snapshot(sim)]) })
    Advance(by) => if sim.now + by > time_limit() then Err("TIME_OVERFLOW") else Ok(Simulator { ..sim, now = sim.now + by })
    Crash => if not(sim.up) then Err("PROCESS_DOWN") else Ok(Simulator { ..sim, up = false })
    Restart => if sim.up then Err("PROCESS_UP") else Ok(Simulator { ..sim, up = true })
    Start(id) => if not(sim.up) then Err("PROCESS_DOWN") elif any(\(r) -> r.id == id, sim.runs) then Err("DUPLICATE_RUN") else
      Ok(Simulator { ..sim, runs = append(sim.runs, [RunState { id = id, status = Active, cancel_requested = false, steps = map(\(d) -> new_step(sim.now, d), workflow.steps) }]) })
    Cancel(id) => if not(sim.up) then Err("PROCESS_DOWN") else cancel_run(sim, id)
    Tick(cp) => tick(sim, workflow, cp)

fn run_commands(sim : Simulator, workflow : Workflow, commands : List(Command)) : Result(Simulator, String) =
  match commands of
    Nil => Ok(sim)
    Cons(c, rest) =>
      let next = apply_command(sim, workflow, c)?
      run_commands(next, workflow, rest)
pub fn simulate(workflow : Workflow) : Result(Simulator, String) = run_commands(new_simulator(), workflow, workflow.commands)

import Data.List (..)
import Data.Foldable (..)
import Domain (..)

pub fn new_service() : MockService = MockService { calls = [], effects = [] }

fn same(a : ActionKey, b : ActionKey) : Bool = a.run_id == b.run_id && a.step_id == b.step_id
fn has_effect(xs : List(Effect), key : ActionKey) : Bool = any(\(x) -> same(x.key, key), xs)
fn transient_count(xs : List(ServiceCall), key : ActionKey) : Int =
  match xs of
    Nil => 0
    Cons(x, rest) => (if x.kind == ExecuteCall && same(x.key, key) && x.outcome == Transient then 1 else 0) + transient_count(rest, key)

pub fn execute(service : MockService, key : ActionKey, amount : Int, attempt : Int, failures : Int) : ServiceResult =
  if has_effect(service.effects, key) then
    ServiceResult { service = MockService { ..service, calls = append(service.calls, [ServiceCall { kind = ExecuteCall, key = key, attempt = attempt, outcome = Replayed }]) }, outcome = Replayed }
  elif transient_count(service.calls, key) < failures then
    ServiceResult { service = MockService { ..service, calls = append(service.calls, [ServiceCall { kind = ExecuteCall, key = key, attempt = attempt, outcome = Transient }]) }, outcome = Transient }
  else
    ServiceResult { service = MockService { calls = append(service.calls, [ServiceCall { kind = ExecuteCall, key = key, attempt = attempt, outcome = Applied }]), effects = append(service.effects, [Effect { key = key, amount = amount }]) }, outcome = Applied }

pub fn lookup(service : MockService, key : ActionKey, attempt : Int) : ServiceResult =
  let outcome = if has_effect(service.effects, key) then Found else Missing
  ServiceResult { service = MockService { ..service, calls = append(service.calls, [ServiceCall { kind = LookupCall, key = key, attempt = attempt, outcome = outcome }]) }, outcome = outcome }

import Data.List (..)
import Data.Foldable (..)
import Data.String (..)
import Data.Result (..)
import Json (..)
import Domain (..)
import Validation (..)
import Runner (simulate)
import Output (response_json)

fn handle_request(line : String) : Result(Simulator, String) =
  let request = map_err(\(_) -> "INVALID_INPUT", decode_lossy(line))?
  let workflow = parse_request(request)?
  simulate(workflow)

fn main() = println(encode(response_json(handle_request(read_line()))))

